// E escrever um comentário em Javascript
console.log("Olá, mundo!"); // Aqui tem outro comentário
console.log("Linha 1");
console.log("Linha 2");
// Comentário de linha única
console.log("Linha 3");
console.log("Linha 4");
// Vai ser ignorado

/*
Comentário de múltiplas linhas
Linha 1
Linha 2
Linha 3
*/

// Não podemos criar variaveis com palavras reservadas
// Variaveis precisam ter nomes significativos
// Não pode começar o nome de uma variavel com numero
// Não podem conter espaços ou traços
// Utilizamos camelCase
// Case-sensitive
// Não podemos redeclarar variaveis com let
// NÃO UTILIZE VAR, POIS ELA TEM PROBLEMAS DE HOISTING E DE ESCOPO
let nomeCompletoDoCliente = "Luiz Fernando";
console.log(nomeCompletoDoCliente);

let umaString = "Um texto";

console.log(` ${umaString} em um lindo dia`);

// ver o tamanho da string
console.log(umaString.length);

// para pegar o último caractere da string
console.log(umaString[umaString.length - 1]);

/**
 * Aritmétcos
 * +  Adição / Concatenção
 * -  Subtração
 * *  Multiplicação
 * /  Divisão
 * ** Potencialização
 * %  Resto da divisão
 * ++ Incremento
 * -- Decremento
 */
// Primeiro os () depois os **, * / % e por último + -

const num1 = 5;
const num2 = 2;
const num3 = 10;
console.log((num1 + num2) * num3);

// ECMAScript 2015 (ES6) - let e const

// Variáveis criadas com var tem escopo global ou de função, enquanto let e const tem escopo de bloco
// Variáveis criadas com var podem ser redeclaradas e atualizadas, enquanto let pode ser atualizada mas não redeclarada, e const não pode ser nem atualizada nem redeclarada
let nome = 'Luiz';
let sobrenome = ' Otávio';

console.log(`meu nome é, ${nome} ${sobrenome}`);

const num1 = 10;
const num2 = Number('5');
console.log(num1 + num2);
console.log(typeof num2);

let num1 = prompt("Digite um número:");
let num2 = prompt("Digite outro número:");

num1 = Number(num1);
num2 = Number(num2);

alert(`O resultado da soma é: ${num1 + num2}`);

let varA = 'A'; // B
let varB = 'B'; // C
let varC = 'C'; // A

const varTemp = varA;
varA = varB;
varB = varC;
varC = varTemp;

console.log(varA, varB, varC);
